import{_ as r,b as e,e as d,a7 as l}from"./chunks/framework.BCCJKnGb.js";const y=JSON.parse('{"title":"2026 级国际新闻与传播培养方案","description":"2026 级国新系本科培养方案：总学分、模块结构、专业核心课与官方原文。","frontmatter":{"title":"2026 级国际新闻与传播培养方案","description":"2026 级国新系本科培养方案：总学分、模块结构、专业核心课与官方原文。","type":"program","grade":2026,"tags":["培养方案","国新系","2026级"],"updated":"2026-11-07T00:00:00.000Z","source":"中国人民大学教务处《2026 级本科生培养方案》"},"headers":[],"relativePath":"programs/2026.md","filePath":"programs/2026.md","lastUpdated":null}'),i={name:"programs/2026.md"};function a(g,t,n,s,h,o){return e(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="_2026-级国际新闻与传播培养方案" tabindex="-1">2026 级国际新闻与传播培养方案 <a class="header-anchor" href="#_2026-级国际新闻与传播培养方案" aria-label="Permalink to &quot;2026 级国际新闻与传播培养方案&quot;">​</a></h1><blockquote><p>适用：2026 年入学的国际新闻与传播专业本科生。<br> 总学分：<strong>127 学分</strong>；学制四年，授予文学学士学位。<br> 原文：<a href="/mingxin-demo/files/programs/2026-%E5%A4%A7%E7%B1%BB%E5%9F%B9%E5%85%BB%E6%96%B9%E6%A1%88.pdf">2026 级大类培养方案（含辅修）PDF</a>。以教务处/学院最新通知为准。</p></blockquote><h2 id="一、模块结构" tabindex="-1">一、模块结构 <a class="header-anchor" href="#一、模块结构" aria-label="Permalink to &quot;一、模块结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th style="text-align:right;">最低学分</th></tr></thead><tbody><tr><td>立本模块</td><td style="text-align:right;">46</td></tr><tr><td>专业模块</td><td style="text-align:right;">65</td></tr><tr><td>卓越模块</td><td style="text-align:right;">16</td></tr><tr><td><strong>合计</strong></td><td style="text-align:right;"><strong>127</strong></td></tr></tbody></table><h2 id="二、关键修读要求" tabindex="-1">二、关键修读要求 <a class="header-anchor" href="#二、关键修读要求" aria-label="Permalink to &quot;二、关键修读要求&quot;">​</a></h2><ul><li><strong>立本模块 46</strong>：思政 14（必修12+选修2）、公共外语 6、公共数学 3、人工智能与数据技术 4、新生引导 1、科学与人文素养 2、公共体育 4、美育 2、劳动教育 1、心理健康 2、职业生涯 1、军事课 4、志愿服务 2。</li><li><strong>专业模块 65</strong>：部类共同课 6、部类基础课 13、专业核心课 32、专业选修 14。</li><li><strong>卓越模块 16</strong>：研究训练 2、专业特色创新训练 2、专业实习 4、毕业论文 4、国际性学习 2、创新引导 2。</li></ul><h2 id="三、专业核心课-主要" tabindex="-1">三、专业核心课（主要） <a class="header-anchor" href="#三、专业核心课-主要" aria-label="Permalink to &quot;三、专业核心课（主要）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>课程</th><th style="text-align:right;">学分</th><th style="text-align:right;">开课学期</th></tr></thead><tbody><tr><td>数智影像技术</td><td style="text-align:right;">2</td><td style="text-align:right;">2</td></tr><tr><td>数智传播应用</td><td style="text-align:right;">2</td><td style="text-align:right;">3</td></tr><tr><td>传播研究方法</td><td style="text-align:right;">2</td><td style="text-align:right;">1</td></tr><tr><td>国际新闻报道（E）</td><td style="text-align:right;">2</td><td style="text-align:right;">3</td></tr><tr><td>马克思主义新闻观与当代中国新闻事业</td><td style="text-align:right;">2</td><td style="text-align:right;">2</td></tr><tr><td>基础写作</td><td style="text-align:right;">2</td><td style="text-align:right;">2</td></tr><tr><td>外国新闻传播史</td><td style="text-align:right;">2</td><td style="text-align:right;">2</td></tr><tr><td>新闻传播学文献阅读</td><td style="text-align:right;">2</td><td style="text-align:right;">1</td></tr><tr><td>中国新闻传播史</td><td style="text-align:right;">2</td><td style="text-align:right;">1</td></tr><tr><td>战略传播</td><td style="text-align:right;">2</td><td style="text-align:right;">4</td></tr><tr><td>新闻传播伦理与法规</td><td style="text-align:right;">2</td><td style="text-align:right;">5</td></tr><tr><td>传媒经营与管理</td><td style="text-align:right;">2</td><td style="text-align:right;">6</td></tr><tr><td>全媒体传播实验Ⅰ</td><td style="text-align:right;">1</td><td style="text-align:right;">4</td></tr><tr><td>全媒体传播实验Ⅱ</td><td style="text-align:right;">1</td><td style="text-align:right;">6</td></tr><tr><td>国际新闻与全球传播（E）</td><td style="text-align:right;">2</td><td style="text-align:right;">4</td></tr><tr><td>英语新闻编译（E）</td><td style="text-align:right;">2</td><td style="text-align:right;">5</td></tr><tr><td>英语新闻评论（E）</td><td style="text-align:right;">2</td><td style="text-align:right;">5</td></tr></tbody></table><blockquote><p>以上为核心课程主体；完整的课程地图、个性化选修课清单、辅修方案见原文 PDF。不同年级课程名称和学分略有调整，选课时以教务系统为准。</p></blockquote><h2 id="四、选课提醒" tabindex="-1">四、选课提醒 <a class="header-anchor" href="#四、选课提醒" aria-label="Permalink to &quot;四、选课提醒&quot;">​</a></h2><ol><li><strong>应修尽修</strong>：必修课按培养方案建议学期修读，无特殊原因不提前、不延后。</li><li><strong>先修关系</strong>：专业核心课之间有先后顺序，先看课程地图再排课。</li><li><strong>个性化选修</strong>：法学类、国际政治类、社会学类、新闻传播学类、本研衔接课程，按模块要求选。</li><li><strong>实践/论文</strong>：专业实习、毕业论文、研究训练不要拖到大四。</li><li><strong>国新特色</strong>：英语新闻采写/编译/评论、国际新闻报道、国际新闻与全球传播等课程，建议连续修读。</li></ol><h2 id="五、来源与更新" tabindex="-1">五、来源与更新 <a class="header-anchor" href="#五、来源与更新" aria-label="Permalink to &quot;五、来源与更新&quot;">​</a></h2><ul><li>来源：中国人民大学教务处《2026 级本科生培养方案》大类培养方案（含辅修）。</li><li>最后核对：2026-11-07。</li><li>说明：本页为结构化整理，不替代官方文件；如与原文不一致，以原文/教务系统为准。</li></ul>',13)])])}const c=r(i,[["render",a]]);export{y as __pageData,c as default};
